mapper.select:
select baseinfo.prod_id prodId, baseinfo.prod_name prodName, substring(bal2.busi_date,1,7) reportDate, bal2.busi_date as busiDate from chb_prd_baseinfo baseinfo left join ( SELECT distinct real_prd_id, busi_date FROM prd_balance bal
substring(busi_date,1,7) = #{reportDate,jdbcType=VARCHAR}
) bal2 on bal2.real_prd_id = baseinfo.prod_id
#{items,jdbcType=VARCHAR}

select bal.real_prd_id realPrdId, bal.subject_id subjectId, bal.subject_name subjectName, bal.ccy ccy, bal.end_bal endBal, bal.begin_bal beginBal, bal.busi_date busiDate, bal.lia_subject_name liaSubjectName, bal.lia_end_bal liaEndBal, bal.lia_begin_bal liaBeginBal from prd_balance bal
substring(bal.busi_date,1,7) = #{reportDate,jdbcType=VARCHAR}
AND bal.real_prd_id = #{prodId,jdbcType=VARCHAR}
ORDER BY bal.subject_id
